"""Unit tests for the mount command generated by sky.data.mounting_utils."""

import os
import pathlib
import subprocess
import tempfile
import unittest

from sky.data import mounting_utils

# Stub the environment the generated mounting script probes: nothing is
# mounted (findmnt), and the mount binary is a no-op that succeeds.
_STUBS = {
    'findmnt': '#!/bin/bash\nexit 1\n',
    'rclone': '#!/bin/bash\necho "STUB_MOUNT_OK"\n',
    'sudo': '#!/bin/bash\nexec "$@"\n',
}


class TestGetMountingCommand(unittest.TestCase):
    """The generated command must run under the real execution shapes."""

    def _run(self, cmd: str, tmp: pathlib.Path) -> subprocess.CompletedProcess:
        stub_dir = tmp / 'bin'
        stub_dir.mkdir(exist_ok=True)
        for name, body in _STUBS.items():
            path = stub_dir / name
            path.write_text(body)
            path.chmod(0o755)
        env = dict(os.environ)
        env['PATH'] = os.pathsep.join([str(stub_dir), env.get('PATH', '')])
        # The command writes its temp script under $HOME/.sky.
        env['HOME'] = str(tmp)
        return subprocess.run(['bash', '-c', cmd],
                              env=env,
                              capture_output=True,
                              text=True,
                              timeout=120,
                              check=False)

    def test_runs_through_the_runner_command_wrapping(self):
        """The command must survive the runners' '... && (cmd)' wrapping.

        Command runners wrap every command as ``true && export ... &&
        (cmd)``. A command that itself starts with ``(`` fuses with that
        wrapper into bash's arithmetic compound ``(( ... ))`` and fails
        with ``bash: ((`` -- which is how every non-Slurm storage mount
        broke when the mktemp form gained a leading subshell.
        """
        with tempfile.TemporaryDirectory() as raw_tmp:
            tmp = pathlib.Path(raw_tmp)
            mount_path = tmp / 'mnt'
            mount_path.mkdir()
            cmd = mounting_utils.get_mounting_command(str(mount_path), 'true',
                                                      'rclone mount')
            wrapped = f'true && export OMP_NUM_THREADS=1 && ({cmd})'
            proc = self._run(wrapped, tmp)

        self.assertEqual(proc.returncode, 0, proc.stdout + proc.stderr)
        self.assertIn('STUB_MOUNT_OK', proc.stdout)
        self.assertNotIn('bash: ((', proc.stderr)
        # The EXIT trap removed the temp script.
        leftovers = list(pathlib.Path(raw_tmp, '.sky').glob('mount_*'))
        self.assertFalse(leftovers, f'temp scripts leaked: {leftovers}')
